Output6[Expected Approach - 1] Using Binary Search - O(log n) Time and O(1) SpaceThe idea is to use the fact that the given array is sorted. We can apply binary search to find the index of the element just larger than the target. Step-by-step implementation:Set variables lo and hi to the starting and ending of array.Find mid = (lo + hi) / 2 and compare arr[mid] with target=> if arr[mid] <= target, then all elements in the range arr[lo...mid] will also be <= target, so update lo = mid+1.=> if arr[mid] > target, then upper bound will lie in the range arr[lo...mid], so update result to mid and update hi = mid - 1.Continue step 2 till lo <= hi.Return result as the upper bound.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int upperBound(vector<int> &arr, int target) { 	
	int lo = 0, hi = arr.size() - 1; 
    int res = arr.size();

  	while(lo <= hi) {
      	int mid = lo + (hi - lo)/2;

        // If arr[mid] > target, then arr[mid] can be
        // the upper bound so store mid in result and
        // search in left half, i.e. arr[lo...mid-1]
      	if(arr[mid] > target) {
          	res = mid;
            hi = mid - 1;
        }

        // If arr[mid] <= target, then upper bound 
        // cannot lie in the range [lo...mid], so 
        // search in right half, i.e. arr[mid+1...hi]
      	else
            lo = mid + 1;
    }
  	return res;
}

int main() {
    vector<int> arr = {2, 3, 7, 10, 11, 11, 25};
    int target = 11;

    cout << upperBound(arr, target);
    return 0;
}


